import SwiftUI
import SwiftData

struct RecurringHomeView: View {
    @Query private var recurring: [RecurringPayment]
    @Query private var installments: [InstallmentPlan]
    @State private var addChoice = false
    @State private var addingRecurring: RecurringKind?
    @State private var addingInstallment = false
    private var subscriptions: [RecurringPayment] { recurring.filter { $0.kind == .subscription } }
    private var customPayments: [RecurringPayment] { recurring.filter { $0.kind == .custom } }
    var body: some View {
        List {
            paymentSection("订阅", items: subscriptions, emptyText: "暂无订阅")
            Section("分期") { if installments.isEmpty { Text("暂无分期").foregroundStyle(.secondary) }; ForEach(installments) { plan in NavigationLink { InstallmentDetailView(plan: plan) } label: { InstallmentRow(plan: plan) } } }
            paymentSection("自订周期", items: customPayments, emptyText: "暂无自订周期")
        }
        .navigationTitle("订阅与分期")
        .toolbar { Button("新增", systemImage: "plus") { addChoice = true } }
        .confirmationDialog("新增项目", isPresented: $addChoice) { Button("订阅") { addingRecurring = .subscription }; Button("分期") { addingInstallment = true }; Button("自订周期") { addingRecurring = .custom } }
        .sheet(item: $addingRecurring) { kind in RecurringEditorView(kind: kind) }
        .sheet(isPresented: $addingInstallment) { InstallmentEditorView() }
    }
    private func paymentSection(_ title: String, items: [RecurringPayment], emptyText: String) -> some View { Section(title) { if items.isEmpty { Text(emptyText).foregroundStyle(.secondary) }; ForEach(items) { payment in NavigationLink { RecurringDetailView(payment: payment) } label: { RecurringRow(payment: payment) } } } }
}

struct RecurringRow: View { let payment: RecurringPayment; var body: some View { HStack { Image(systemName: payment.symbolName).foregroundStyle(.tint).frame(width: 38, height: 38).background(Color.accentColor.opacity(0.12), in: RoundedRectangle(cornerRadius: 10)); VStack(alignment: .leading) { Text(payment.name).font(.headline); Text("下次扣款 · " + payment.nextPaymentDate.formatted(DateFormats.shortDay)).font(.caption).foregroundStyle(.secondary) }; Spacer(); AmountText(amount: payment.amount, currency: payment.currency) } } }
struct InstallmentRow: View { let plan: InstallmentPlan; var body: some View { VStack(alignment: .leading, spacing: 8) { HStack { VStack(alignment: .leading) { Text(plan.name).font(.headline); Text("下次扣款 · " + plan.nextPaymentDate.formatted(DateFormats.shortDay)).font(.caption).foregroundStyle(.secondary) }; Spacer(); AmountText(amount: plan.totalAmount) }; ProgressView(value: plan.installmentCount > 0 ? Double(plan.paidInstallments) / Double(plan.installmentCount) : 0); Text("已入账 \(plan.paidInstallments) 期 · 剩余 \(max(0, plan.installmentCount - plan.paidInstallments)) 期 · 共 \(plan.installmentCount) 期").font(.caption).foregroundStyle(.secondary) } } }
struct RecurringDetailView: View { @Environment(\.modelContext) private var context; @Environment(\.dismiss) private var dismiss; let payment: RecurringPayment; @State private var editing = false; @State private var deleting = false; var body: some View { List { Section { RecurringRow(payment: payment) }; Section("计划") { LabeledContent("周期", value: "每 \(payment.interval) " + payment.frequency.title); LabeledContent("付款账户", value: payment.account?.name ?? "—"); LabeledContent("分类", value: payment.category?.name ?? "—"); LabeledContent("自动生成账单", value: payment.autoCreateTransaction ? "开启" : "关闭"); LabeledContent("提前提醒", value: "\(payment.notificationDaysBefore) 天") }; Section { Button("删除", systemImage: "trash", role: .destructive) { deleting = true }.frame(maxWidth: .infinity) } }.navigationTitle(payment.name).toolbar { Button("编辑") { editing = true } }.sheet(isPresented: $editing) { RecurringEditorView(kind: payment.kind, payment: payment) }.confirmationDialog("删除项目？", isPresented: $deleting) { Button("删除", role: .destructive) { context.delete(payment); try? context.save(); dismiss() } } } }
struct RecurringEditorView: View { @Environment(\.dismiss) private var dismiss; @Environment(\.modelContext) private var context; @Query private var accounts: [Account]; @Query private var categories: [FinanceCategory]; let kind: RecurringKind; var payment: RecurringPayment?; @State private var name: String; @State private var amount: String; @State private var currency: String; @State private var frequency: Frequency; @State private var interval: Int; @State private var nextDate: Date; @State private var account: Account?; @State private var category: FinanceCategory?; @State private var note: String; @State private var automatic: Bool; @State private var reminder: Int; @State private var errorMessage: String?; init(kind: RecurringKind, payment: RecurringPayment? = nil) { self.kind = kind; self.payment = payment; _name = State(initialValue: payment?.name ?? ""); _amount = State(initialValue: payment.map { "\($0.amount)" } ?? ""); _currency = State(initialValue: payment?.currency ?? "CNY"); _frequency = State(initialValue: payment?.frequency ?? .monthly); _interval = State(initialValue: payment?.interval ?? 1); _nextDate = State(initialValue: payment?.nextPaymentDate ?? .now); _account = State(initialValue: payment?.account); _category = State(initialValue: payment?.category); _note = State(initialValue: payment?.note ?? ""); _automatic = State(initialValue: payment?.autoCreateTransaction ?? false); _reminder = State(initialValue: payment?.notificationDaysBefore ?? 1) }; var body: some View { NavigationStack { Form { TextField("名称", text: $name); TextField("金额", text: $amount).keyboardType(.decimalPad); Picker("币种", selection: $currency) { ForEach(["CNY", "USD", "EUR", "JPY"], id: \.self) { code in Text(code) } }; Picker("周期", selection: $frequency) { ForEach(Frequency.allCases) { item in Text(item.title).tag(item) } }; Stepper("每 \(interval) 个周期", value: $interval, in: 1...99); DatePicker("下次扣款", selection: $nextDate); Picker("账户", selection: $account) { Text("未选择").tag(nil as Account?); ForEach(accounts) { item in Text(item.name).tag(Optional(item)) } }; Picker("分类", selection: $category) { Text("未选择").tag(nil as FinanceCategory?); ForEach(categories.filter { $0.type == .expense }) { item in Text(item.name).tag(Optional(item)) } }; Toggle("自动生成账单", isOn: $automatic); Stepper("提前 \(reminder) 天提醒", value: $reminder, in: 0...30); TextField("备注", text: $note) }.navigationTitle(payment == nil ? "新增\(kind.title)" : "编辑\(kind.title)").toolbar { ToolbarItem(placement: .cancellationAction) { Button("取消") { dismiss() } }; ToolbarItem(placement: .confirmationAction) { Button("保存") { save() } } }.alert("无法保存", isPresented: .constant(errorMessage != nil)) { Button("好") { errorMessage = nil } } message: { Text(errorMessage ?? "") } } }; private func save() { guard let value = Decimal(string: amount), value > 0, !name.isEmpty else { errorMessage = "请填写有效名称和金额"; return }; let model = payment ?? RecurringPayment(kind: kind, name: name, amount: value); model.name = name; model.amount = value; model.currency = currency; model.frequencyRaw = frequency.rawValue; model.interval = interval; model.nextPaymentDate = nextDate; model.account = account; model.category = category; model.note = note; model.autoCreateTransaction = automatic; model.notificationDaysBefore = reminder; if payment == nil { context.insert(model) }; do { try context.save(); dismiss() } catch { errorMessage = error.localizedDescription } } }
struct InstallmentDetailView: View { @Environment(\.modelContext) private var context; @Environment(\.dismiss) private var dismiss; let plan: InstallmentPlan; @State private var editing = false; @State private var deleting = false; var body: some View { List { Section { InstallmentRow(plan: plan) }; Section("分期信息") { LabeledContent("总金额", value: CurrencyFormatter.string(plan.totalAmount)); LabeledContent("首付", value: CurrencyFormatter.string(plan.downPayment)); LabeledContent("每期金额", value: CurrencyFormatter.string(plan.installmentAmount)); LabeledContent("手续费", value: CurrencyFormatter.string(plan.fee)); LabeledContent("付款账户", value: plan.account?.name ?? "—"); LabeledContent("开始日期", value: plan.startDate.formatted(DateFormats.shortDay)) }; if plan.paidInstallments < plan.installmentCount { Section { Button("标记一期已还", systemImage: "checkmark.circle") { plan.paidInstallments += 1; plan.nextPaymentDate = Calendar.current.date(byAdding: .month, value: 1, to: plan.nextPaymentDate) ?? plan.nextPaymentDate; try? context.save() }.frame(maxWidth: .infinity) } }; Section { Button("删除分期", systemImage: "trash", role: .destructive) { deleting = true }.frame(maxWidth: .infinity) } }.navigationTitle(plan.name).toolbar { Button("编辑") { editing = true } }.sheet(isPresented: $editing) { InstallmentEditorView(plan: plan) }.confirmationDialog("删除分期？", isPresented: $deleting) { Button("删除", role: .destructive) { context.delete(plan); try? context.save(); dismiss() } } } }
struct InstallmentEditorView: View { @Environment(\.dismiss) private var dismiss; @Environment(\.modelContext) private var context; @Query private var accounts: [Account]; var plan: InstallmentPlan?; @State private var name: String; @State private var total: String; @State private var down: String; @State private var count: Int; @State private var paid: Int; @State private var each: String; @State private var start: Date; @State private var next: Date; @State private var account: Account?; @State private var fee: String; @State private var note: String; @State private var errorMessage: String?; init(plan: InstallmentPlan? = nil) { self.plan = plan; _name = State(initialValue: plan?.name ?? ""); _total = State(initialValue: plan.map { "\($0.totalAmount)" } ?? ""); _down = State(initialValue: plan.map { "\($0.downPayment)" } ?? "0"); _count = State(initialValue: plan?.installmentCount ?? 12); _paid = State(initialValue: plan?.paidInstallments ?? 0); _each = State(initialValue: plan.map { "\($0.installmentAmount)" } ?? ""); _start = State(initialValue: plan?.startDate ?? .now); _next = State(initialValue: plan?.nextPaymentDate ?? .now); _account = State(initialValue: plan?.account); _fee = State(initialValue: plan.map { "\($0.fee)" } ?? "0"); _note = State(initialValue: plan?.note ?? "") }; var body: some View { NavigationStack { Form { TextField("商品名称", text: $name); TextField("总金额", text: $total).keyboardType(.decimalPad); TextField("首付", text: $down).keyboardType(.decimalPad); Stepper("共 \(count) 期", value: $count, in: 1...120); Stepper("已还 \(paid) 期", value: $paid, in: 0...count); TextField("每期金额", text: $each).keyboardType(.decimalPad); TextField("手续费", text: $fee).keyboardType(.decimalPad); DatePicker("开始日期", selection: $start, displayedComponents: .date); DatePicker("下一期", selection: $next, displayedComponents: .date); Picker("账户", selection: $account) { Text("未选择").tag(nil as Account?); ForEach(accounts) { item in Text(item.name).tag(Optional(item)) } }; TextField("备注", text: $note) }.navigationTitle(plan == nil ? "新增分期" : "编辑分期").toolbar { ToolbarItem(placement: .cancellationAction) { Button("取消") { dismiss() } }; ToolbarItem(placement: .confirmationAction) { Button("保存") { save() } } }.alert("无法保存", isPresented: .constant(errorMessage != nil)) { Button("好") { errorMessage = nil } } message: { Text(errorMessage ?? "") } } }; private func save() { guard let totalValue = Decimal(string: total), totalValue > 0, let downValue = Decimal(string: down), let eachValue = Decimal(string: each), eachValue > 0, let feeValue = Decimal(string: fee), !name.isEmpty else { errorMessage = "请填写有效名称和金额"; return }; let model = plan ?? InstallmentPlan(name: name, totalAmount: totalValue, installmentCount: count, installmentAmount: eachValue); model.name = name; model.totalAmount = totalValue; model.downPayment = downValue; model.installmentCount = count; model.paidInstallments = min(paid, count); model.installmentAmount = eachValue; model.startDate = start; model.nextPaymentDate = next; model.account = account; model.fee = feeValue; model.note = note; if plan == nil { context.insert(model) }; do { try context.save(); dismiss() } catch { errorMessage = error.localizedDescription } } }
